from experiments import *

def nearby(x,r=8):
    out=[x]; up=down=x
    for _ in range(r):
        up=math.nextafter(up,math.inf); down=math.nextafter(down,-math.inf)
        out.extend([down,up])
    return sorted(out)

def main():
    gains=decoded('seasonal-stage1'); obs=decoded('seasonal-stage2')
    rows=[]; cases=[]
    for c in seasonal_cases()+[dict(id='B5',y=[float(256*j+(48 if j==8 else 0)) for j in range(12)],p=4)]:
        name=c['id']; a,b,g=[gains[name+'_S'+str(k)] for k in range(1,4)]
        sigma=obs[name+'_Cendpoint']; c1=obs[name+'_C1']; z=1.9599639845400536
        vs=[v for v in nearby(sigma*sigma) if bits(math.sqrt(v))==bits(sigma)]
        vs=[v for v in vs if bits(xop(z,math.sqrt(v),'mul'))==bits(c1)]
        assert vs,(name,sigma,c1)
        cases.append(dict(id=name,sigma=val(sigma),variance_candidates=[val(v) for v in vs],
            protocol='All nearby binary64 variances whose rounded sqrt equals observed endpoint and whose stored-PC64 z product equals observed C1. Entire rounding preimage is enclosed by +/-8 ulps.'))
        for h in sorted(set([c['p']+2,2*c['p']+1,3*c['p']+1])):
            for output,zvalue in [('endpoint',1.),('confidence',z)]:
                preds={}
                for convention,geff in [('innovation',g),('traditional',(1.-a)*g)]:
                    vh=variance(a,b,geff,c['p'],h)
                    for v in vs:
                        preds[convention+'_'+bits(v)]=val(xop(zvalue,math.sqrt(v*vh),'mul'))
                rows.append(question(f'{name}_{output}_h{h}',c['y'],c['p'],output,h,preds))
    save('covariance-followup-predictions.json',dict(
      protocol='Conditional covariance test; residual variance is a finite rounding preimage, not a fitted scalar. All predictions frozen before new horizons. Same operation grouping as nonseasonal ets.rs with phase p.',
      python_source=Path(__file__).read_text(),cases=cases,rows=rows))
    print('Frozen',len(rows),'covariance readings')

if __name__=='__main__':main()
